'use strict';
const $=id=>document.getElementById(id),pct=x=>(100*x).toFixed(2)+'%';
DATA.motions.forEach((m,i)=>$('motion').add(new Option(`${m.id} · ${m.category.replaceAll('_',' ')}`,i)));
Object.keys(DATA.prob).forEach(k=>$('model').add(new Option(k==='analytic_target'?'Label oracle (uses geometry)':k==='explicit_event'?'Explicit motion-change rule':k==='uniform'?'Uniform recipes':k,k)));$('model').value='hindsight-801';
function specs(m=+$('motion').value){return DATA.routeSpec?DATA.routeSpec[m]:DATA.spec;}
let selected=0,busy=false,pending=false,playing=false,last=0;
function distribution(raw,m){const z=raw.reduce((a,p,j)=>a+p*(DATA.lower[m][j]>=.02),0);return{q:$('mode').value==='raw'?raw:raw.map((p,j)=>z>0&&DATA.lower[m][j]>=.02?p/z:0),z};}
function state(){const m=+$('motion').value,key=$('model').value;const d=distribution(DATA.prob[key][m],m);const ref=key.includes('802')?'hindsight_no_motion-802':'hindsight_no_motion-801';return{m,...d,baseline:distribution(DATA.prob[ref][m],m).q};}
function obstacle(){const[x,y,z,k,yaw=0]=specs()[selected],v=[],f=[];if(k===2){for(let a=0;a<=12;a++)for(let b=0;b<20;b++){const t=Math.PI*a/12,p=2*Math.PI*b/20;v.push([x+.3*Math.sin(t)*Math.cos(p),y+.3*Math.sin(t)*Math.sin(p),z+.3*Math.cos(t)]);}for(let a=0;a<12;a++)for(let b=0;b<20;b++){let u=a*20+b,w=a*20+(b+1)%20;f.push([u,w,u+20],[w,w+20,u+20]);}}else{const h=k===0?[.15,.8,.1]:[.3,.3,.4];for(const a of [-1,1])for(const b of [-1,1])for(const c of [-1,1])v.push([x+a*h[0],y+b*h[1],z+c*h[2]]);f.push([0,1,3],[0,3,2],[4,6,7],[4,7,5],[0,4,5],[0,5,1],[2,3,7],[2,7,6],[0,2,6],[0,6,4],[1,5,7],[1,7,3]);}if(yaw){for(const p of v){const dx=p[0]-x,dy=p[1]-y;p[0]=x+Math.cos(yaw)*dx-Math.sin(yaw)*dy;p[1]=y+Math.sin(yaw)*dx+Math.cos(yaw)*dy;}}return{type:'mesh3d',x:v.map(p=>p[0]),y:v.map(p=>p[1]),z:v.map(p=>p[2]),i:f.map(p=>p[0]),j:f.map(p=>p[1]),k:f.map(p=>p[2]),color:'#e3af65',opacity:.55,hoverinfo:'skip',flatshading:true};}
function robot(m,frame){if($('robot').value==='joints'){const p=DATA.motions[m].positions[frame];return[{type:'scatter3d',mode:'markers',x:p.map(v=>v[0]),y:p.map(v=>v[1]),z:p.map(v=>v[2]),marker:{size:4,color:'#c9eaf2'},hoverinfo:'skip'}];}return DATA.mesh.map((g,i)=>{const{r,p}=DATA.motions[m].mesh_poses[frame][i],v=g.v.map(a=>[p[0]+r[0]*a[0]+r[1]*a[1]+r[2]*a[2],p[1]+r[3]*a[0]+r[4]*a[1]+r[5]*a[2],p[2]+r[6]*a[0]+r[7]*a[1]+r[8]*a[2]]);return{type:'mesh3d',x:v.map(a=>a[0]),y:v.map(a=>a[1]),z:v.map(a=>a[2]),i:g.f.map(a=>a[0]),j:g.f.map(a=>a[1]),k:g.f.map(a=>a[2]),color:`rgb(${g.color.map(x=>Math.round(x*255)).join(',')})`,hoverinfo:'skip',lighting:{ambient:.6,diffuse:.8,specular:.3},flatshading:false};});}
async function draw(){if(busy){pending=true;return;}busy=true;try{const{m,q,z,baseline}=state(),motion=DATA.motions[m],frame=Math.min(+$('frame').value,motion.times.length-1);$('frame').max=motion.times.length-1;const kind=+$('kind').value,ids=specs().map((s,j)=>j).filter(j=>specs()[j][3]===kind);const sum=fn=>q.reduce((a,p,j)=>a+p*fn(j),0);
$('contrast').textContent=pct(sum(j=>DATA.lower[m][j]>=.02&&Math.min(...DATA.cfUpper[m][j])<0));$('near').textContent=pct(sum(j=>DATA.lower[m][j]>=.02&&DATA.upper[m][j]<=.12));$('clear').textContent=pct(sum(j=>DATA.lower[m][j]>=.02));$('hit').textContent=pct(sum(j=>DATA.upper[m][j]<0));$('unknown').textContent=pct(sum(j=>DATA.lower[m][j]<.02&&DATA.upper[m][j]>=0));$('prompt').textContent=motion.prompts.join(' → ');$('time').textContent=`${motion.times[frame].toFixed(2)} / ${motion.times.at(-1).toFixed(2)} s`;
$('mass').textContent=`Filter retains ${pct(z)} of raw mass · Displayed shape mass ${pct(sum(j=>specs()[j][3]===kind))}, not renormalized · Fixed color scale across motions for this model`;
$('support').textContent=`HINDSIGHT v3 · Motion features: COM, hip, head, hands and feet. Event anchors use an explicit motion-change rule. ${DATA.lower[m].filter((v,j)=>v>=.02&&Math.min(...DATA.cfUpper[m][j])<0).length} / 225 candidates show the kinematic contrast proxy in this motion. This is not a physical decision-utility result.`;
const color=$('color').value,values=ids.map(j=>color==='prob'?q[j]:color==='delta'?q[j]-baseline[j]:color==='contrast'?(DATA.lower[m][j]>=.02&&Math.min(...DATA.cfUpper[m][j])<0?1:0):DATA.lower[m][j]>=.02?1:DATA.upper[m][j]<0?-1:0);let max=0;for(let mm=0;mm<DATA.motions.length;mm++){const d=distribution(DATA.prob[$('model').value][mm],mm).q;max=Math.max(max,...d);}const scale=color==='prob'?max:(color==='bounds'||color==='contrast')?1:Math.max(max,...baseline);
const cloud={type:'scatter3d',mode:'markers',x:ids.map(j=>specs()[j][0]),y:ids.map(j=>specs()[j][1]),z:ids.map(j=>specs()[j][2]),customdata:ids,text:ids.map(j=>`Cell ${j}<br>q = ${pct(q[j])}<br>Lower bound ${DATA.lower[m][j].toFixed(3)} m<br>Inner upper ${DATA.upper[m][j].toFixed(3)} m`),hovertemplate:'%{text}<extra></extra>',marker:{size:ids.map(j=>4+10*Math.sqrt(q[j]/Math.max(max,1e-12))),opacity:.85,color:values,cmin:color==='prob'||color==='contrast'?0:-scale,cmax:scale,colorscale:color==='prob'?'Viridis':color==='delta'?'RdBu':color==='contrast'?[[0,'#263e57'],[1,'#ec76e8']]:[[0,'#ff816f'],[.5,'#edc868'],[1,'#54dfae']],showscale:true,colorbar:{title:{text:color==='prob'?'q per cell':color==='delta'?'q − no-motion':color==='contrast'?'Contrast proxy':'Geometry'},thickness:12,len:.7}}};
const root=motion.positions.map(p=>p[0]),path={type:'scatter3d',mode:'lines+markers',x:root.map(p=>p[0]),y:root.map(p=>p[1]),z:root.map(p=>p[2]),line:{color:'#70cbe8',width:4},marker:{size:4,color:motion.times.map(t=>motion.motion_analysis.saliency[Math.round(t*motion.fps)]),colorscale:'Plasma',cmin:0,cmax:3},text:motion.times.map(t=>t.toFixed(2)+' s · event score '+motion.motion_analysis.saliency[Math.round(t*motion.fps)].toFixed(2)),hovertemplate:'Root time %{text}<extra></extra>'};
const anchors=motion.anchors||[];const footprint={type:'scatter3d',mode:'markers',x:anchors.map(a=>a[0]),y:anchors.map(a=>a[1]),z:anchors.map(()=>0),marker:{color:'#efc16e',size:7,symbol:'diamond'},hovertemplate:'Route anchor<extra></extra>'};
const endpoints={type:'scatter3d',mode:'markers+text',x:[root[0][0],root.at(-1)[0]],y:[root[0][1],root.at(-1)[1]],z:[root[0][2],root.at(-1)[2]],text:['START','END'],textposition:'top center',marker:{size:6,color:['#72edb1','#ffad72']},hoverinfo:'text'};
await Plotly.react($('plot'),[cloud,path,obstacle(),...robot(m,frame),footprint,endpoints,bodyOverlay(m,frame)],{paper_bgcolor:'#0b1420',font:{color:'#bccedc'},margin:{l:0,r:0,t:0,b:0},showlegend:false,uirevision:'camera',scene:{aspectmode:'data',camera:{eye:{x:1.65,y:-1.8,z:1.05}},xaxis:{title:{text:'x (m)'},gridcolor:'#24364a'},yaxis:{title:{text:'y (m)'},gridcolor:'#24364a'},zaxis:{title:{text:'z (m)'},gridcolor:'#24364a'}}},{responsive:true,displaylogo:false});
const s=specs()[selected],lo=DATA.lower[m][selected],up=DATA.upper[m][selected];$('detail').textContent=`Cell ${selected} · ${['beam','box','sphere'][s[3]]} at (${s.slice(0,3).map(v=>v.toFixed(2)).join(', ')}) m · yaw ${((s[4]||0)*180/Math.PI).toFixed(1)}° · q ${pct(q[selected])} · raw q ${pct(DATA.prob[$('model').value][m][selected])}. Lower bound ${lo.toFixed(3)} m; inner upper ${up.toFixed(3)} m. ${lo>=.02?'Certified clear by bound':up<0?'Penetration witness':'Unknown / insufficient margin'}. ${lo>=.02&&up<=.12?'Sufficient near-boundary candidate. ':''}Shortcut upper ${DATA.cfUpper[m][selected][0].toFixed(3)} m; held-pose upper ${DATA.cfUpper[m][selected][1].toFixed(3)} m. Anchor time ${motion.events.anchor_times[Math.floor(selected/45)].toFixed(2)} s. Physical passage: untested.`;
$('status').textContent=q.reduce((a,b)=>a+b,0)===0?'ABSTAIN: no certified probability mass.':'';await drawAnalysis(m,frame);window.VIEWER_READY=true;
}catch(e){$('error').textContent=e.message;throw e;}finally{busy=false;if(pending){pending=false;draw();}}}
for(const id of ['motion','model','mode','kind','color','robot','bodypart','signal'])$(id).onchange=()=>{if(id==='motion'){$('frame').value=0;playing=false;$('play').textContent='Play';}draw();};$('frame').oninput=draw;
$('sample').onclick=()=>{const{q}=state(),total=q.reduce((a,b)=>a+b,0);if(total<=0){$('status').textContent='ABSTAIN: cannot sample an empty distribution.';return;}let r=Math.random()*total;selected=q.length-1;for(let j=0;j<q.length;j++){r-=q[j];if(r<0){selected=j;break;}}$('kind').value=specs()[selected][3];draw();};
$('closest').onclick=()=>{const{m}=state(),s=specs()[selected];let best=Infinity,index=0;DATA.motions[m].positions.forEach((p,t)=>p.forEach(v=>{const d=v.reduce((a,x,i)=>a+(x-s[i])**2,0);if(d<best){best=d;index=t;}}));$('frame').value=index;draw();};
$('play').onclick=()=>{playing=!playing;last=performance.now();$('play').textContent=playing?'Pause':'Play';};
setInterval(()=>{if(!playing||busy)return;const motion=DATA.motions[+$('motion').value],i=+$('frame').value,now=performance.now(),next=(i+1)%motion.times.length;const dt=next===0?.3:motion.times[next]-motion.times[i];if(now-last>=dt*1000){$('frame').value=next;last=now;draw();}},30);
draw().then(()=>{$('analysisplot').on('plotly_click',e=>{const t=e.points[0].x,m=DATA.motions[+$('motion').value];let best=0;m.times.forEach((v,i)=>{if(Math.abs(v-t)<Math.abs(m.times[best]-t))best=i;});$('frame').value=best;draw();});$('plot').on('plotly_click',e=>{if(e.points[0].curveNumber===0){selected=e.points[0].customdata;draw();}});});

function bodyOverlay(m,frame){const motion=DATA.motions[m],i=Math.round(motion.times[frame]*motion.fps),points=motion.motion_analysis.points[i],part=+$('bodypart').value;return{type:'scatter3d',mode:'markers+text',x:points.map(p=>p[0]),y:points.map(p=>p[1]),z:points.map(p=>p[2]),text:points.map((p,j)=>j===part?['COM','Hip','Head','L hand','R hand','L foot','R foot'][j]:''),textposition:'top center',marker:{size:points.map((p,j)=>j===part?8:3),color:['#ffa760','#c2f3ee','#f175d3','#71e6e8','#71e6e8','#ebda67','#ebda67']},hoverinfo:'text'};}
async function drawAnalysis(m,frame){const motion=DATA.motions[m],a=motion.motion_analysis,part=+$('bodypart').value,signal=$('signal').value;let y,title;if(signal==='turn'){y=a.turn_rate;title='Route turn rate (rad/s)';}else if(signal==='chord'){y=a.chord_deviation;title='Root shortcut deviation (m)';}else if(signal==='saliency'){y=a.saliency;title='Explicit event score';}else if(signal==='height'){y=a.points.map(p=>p[part][2]);title='Point height (m)';}else if(signal==='orientation'){y=part===0?a.times.map(()=>null):a.angular_speed.map(p=>p[part-1]);title=part===0?'COM has no orientation':'Body angular speed (rad/s)';}else{y=a[signal].map(p=>p[part]);title=signal==='speed'?'Point speed (m/s)':'Point acceleration (m/s²)';}const shapes=motion.events.anchor_times.map(t=>({type:'line',x0:t,x1:t,y0:0,y1:1,yref:'paper',line:{color:'#e16e75',width:1,dash:'dot'}}));shapes.push({type:'line',x0:motion.times[frame],x1:motion.times[frame],y0:0,y1:1,yref:'paper',line:{color:'#f4d468',width:2}});await Plotly.react($('analysisplot'),[{type:'scatter',mode:'lines',x:a.times,y,line:{color:'#70dcca',width:2},hovertemplate:'%{x:.2f} s · %{y:.3f}<extra></extra>'}],{paper_bgcolor:'#0b1420',plot_bgcolor:'#122136',font:{color:'#bcd2e1'},margin:{l:65,r:15,t:25,b:40},title:{text:title,font:{size:13}},xaxis:{title:{text:'Time (s)'}},yaxis:{automargin:true},shapes,uirevision:m+'-'+signal+'-'+part},{responsive:true,displaylogo:false});}
